    "title": "TSD: Catalogue Sync — Product, Price & Inventory (MuleSoft → SFCC)",
    "type": "page",
    "created": "",
    "updated": "",
    "url": "https://zimmermannworkboard.atlassian.net/wiki/spaces/SFCC/pages/312508418",
